// Pull the JSON object out of Claude's reply and check the fields the pipeline needs.
const config = $('Config').first().json;
const text = ($json.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end <= start) throw new Error('Claude did not return JSON: ' + text.slice(0, 300));
const beats = JSON.parse(text.slice(start, end + 1));

if (!Array.isArray(beats.beats) || beats.beats.length === 0) throw new Error('Script has no beats');
beats.characters = Array.isArray(beats.characters) && beats.characters.length
  ? beats.characters
  : [{ id: 'main_character', description: 'friendly stylized 3D cartoon person, big expressive eyes, simple clothes' }];
const characterIds = new Set(beats.characters.map((c) => c.id));

const slug = String(beats.project_name || config.topic)
  .toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'zackd_short';
beats.project_name = slug + '_' + $execution.id;
beats.topic = beats.topic || config.topic;
beats.aspect_ratio = config.aspectRatio;

beats.beats.forEach((beat, b) => {
  beat.beat_id = beat.beat_id || 'beat_' + (b + 1);
  if (!beat.narration) throw new Error(beat.beat_id + ' has no narration');
  if (!Array.isArray(beat.shots) || beat.shots.length === 0) throw new Error(beat.beat_id + ' has no shots');
  beat.shots.forEach((shot, s) => {
    shot.shot_id = beat.beat_id + '_' + 'abcdefgh'[s];
    shot.duration_sec = Math.min(4, Math.max(2, Number(shot.duration_sec) || 3));
    shot.camera_move = shot.camera_move || 'push_in';
    shot.zoom_impact = Boolean(shot.zoom_impact);
    shot.character_refs = (shot.character_refs || []).filter((id) => characterIds.has(id));
  });
});

return [{ json: beats }];

