// One turnaround sheet per recurring character keeps the look stable across shots.
const beats = $('Parse beats.json').first().json;
const config = $('Config').first().json;
return beats.characters.map((c) => ({
  json: {
    tag: c.id,
    endpoint: config.imageEndpoint,
    payload: {
      prompt: 'Orthographic 3D character turnaround sheet, front view, side profile and 3/4 view of ' + c.description +
        '. Stylized 3D digital art, smooth plasticine shader, clean light grey background, octane render, studio lighting.',
      aspect_ratio: '16:9',
    },
  },
}));

// Each shot's keyframe prompt repeats the character descriptions so the image model keeps identities.
const beats = $('Parse beats.json').first().json;
const config = $('Config').first().json;
const characters = Object.fromEntries(beats.characters.map((c) => [c.id, c.description]));
// Turnaround sheets exist only when Config.imageEditEndpoint is set; then they go to the edit model as references.
const sheets = $('Render character sheets').isExecuted
  ? Object.fromEntries($('Render character sheets').all().map((i) => [i.json.tag, i.json.url]))
  : {};

const jobs = [];
for (const beat of beats.beats) {
  for (const shot of beat.shots) {
    const anchors = shot.character_refs.map((id) => id + ': ' + characters[id]).join('; ');
    const refs = shot.character_refs.map((id) => sheets[id]).filter(Boolean);
    jobs.push({
      json: {
        tag: shot.shot_id,
        endpoint: refs.length ? config.imageEditEndpoint : config.imageEndpoint,
        payload: {
          ...(refs.length ? { [config.referenceImagesField]: refs } : {}),
          prompt: 'Stylized 3D render, Zack D Films visual aesthetic, plasticine clay subsurface scattering: ' +
            shot.scene_description +
            '. Dramatic studio key light, vibrant rim lighting, crisp ambient occlusion, macro depth of field.' +
            (anchors ? ' Characters: ' + anchors + '.' : ''),
          aspect_ratio: config.aspectRatio,
        },
      },
    });
  }
}
return jobs;

