    if (!keyframes[shot.shot_id]) throw new Error('No keyframe for ' + shot.shot_id);
    jobs.push({
      json: {
        tag: shot.shot_id,
        endpoint: config.videoEndpoint,
        payload: {
          image_url: keyframes[shot.shot_id],
          prompt: 'Smooth 3D animation, camera movement ' + shot.camera_move.replace(/_/g, ' ') + '. ' + shot.scene_description,
          aspect_ratio: config.aspectRatio,
          resolution: config.videoResolution,
        },
      },
    });
  }
}
return jobs;

const beats = $('Parse beats.json').first().json;
const config = $('Config').first().json;
return [{
  json: {
    tag: 'narration',
    endpoint: config.ttsEndpoint,
    payload: {
      text: beats.beats.map((b) => b.narration.trim()).join(' '),
      voice_id: config.voiceId,
      speed: config.speechSpeed,
    },
  },
}];

const beats = $('Parse beats.json').first().json;
const config = $('Config').first().json;
const workDir = config.outputDir + '/' + beats.project_name + '_work';
const media = $('Animate clips').all().map((i) => ({ json: { url: i.json.url, file: workDir + '/' + i.json.tag + '.mp4' } }));
media.push({ json: { url: $('Narrate').first().json.url, file: workDir + '/narration.audio' } });
return media;

// Port of scripts/assemble.py: 720x1280 canvas, impact zoom, cycling xfade transitions.
// Shot lengths are scaled so the cut matches the narration, then narration (and optional BGM) is the soundtrack.
const W = 720, H = 1280, FPS = 30, MAX_CLIP = 7.5;
const TRANSITIONS = ['fade', 'wipeleft', 'slideleft', 'circleopen'];
const beats = $('Parse beats.json').first().json;
const config = $('Config').first().json;
const workDir = config.outputDir + '/' + beats.project_name + '_work';
const narrationWav = workDir + '/narration.wav';
const narrationSec = parseFloat($json.stdout);
if (!(narrationSec > 0)) throw new Error('Could not read narration length: ' + $json.stdout + ' ' + $json.stderr);

const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";
const n = (v) => v.toFixed(3);
const shots = beats.beats.flatMap((b) => b.shots);
const t = Math.max(0, config.transitionDuration);

// Fit the planned durations to the narration, keeping each shot inside the generated clip.
const planned = shots.reduce((sum, s) => sum + s.duration_sec, 0) - t * (shots.length - 1);
const scale = (narrationSec + 0.4) / planned;
const durations = shots.map((s) => Math.min(MAX_CLIP, Math.max(t + 0.5, s.duration_sec * scale)));

const inputs = [];
const filters = [];
shots.forEach((shot, i) => {
  inputs.push('-i ' + q(workDir + '/' + shot.shot_id + '.mp4'));
  let v = '[' + i + ':v]trim=duration=' + n(durations[i]) + ',setpts=PTS-STARTPTS,fps=' + FPS +
    ',scale=' + W + ':' + H + ':force_original_aspect_ratio=increase,crop=' + W + ':' + H + ',setsar=1,settb=AVTB';
  if (shot.zoom_impact) {
    v += ',scale=' + (W + 36) + ':' + (H + 64) + ':flags=lanczos,crop=' + W + ':' + H + ':(iw-' + W + ')/2:(ih-' + H + ')/2';
  }
  filters.push(v + ',format=yuv420p[v' + i + ']');
});

let previous = 'v0';
let timeline = durations[0];
for (let i = 1; i < shots.length; i++) {
  if (t > 0) {
    const d = Math.min(t, durations[i], timeline);
    filters.push('[' + previous + '][v' + i + ']xfade=transition=' + TRANSITIONS[(i - 1) % TRANSITIONS.length] +
      ':duration=' + n(d) + ':offset=' + n(timeline - d) + '[vx' + i + ']');
    timeline += durations[i] - d;
  } else {
    filters.push('[' + previous + '][v' + i + ']concat=n=2:v=1:a=0[vx' + i + ']');
    timeline += durations[i];
  }
  previous = 'vx' + i;
}
// Hold the last frame if the narration still runs past the final cut.
filters.push('[' + previous + ']tpad=stop_mode=clone:stop_duration=10[vout]');

const narrationIndex = shots.length;
inputs.push('-i ' + q(narrationWav));
filters.push('[' + narrationIndex + ':a]highpass=f=80,lowpass=f=8000,volume=1.2,aresample=48000[narr]');
if (config.bgmPath) {
  inputs.push('-stream_loop -1 -i ' + q(config.bgmPath));
  filters.push('[' + (narrationIndex + 1) + ':a]volume=0.15,aresample=48000[bgm]');
  filters.push('[narr][bgm]amix=inputs=2:duration=first:dropout_transition=0[aout]');
} else {
  filters.push('[narr]anull[aout]');
}

const outFile = config.outputDir + '/' + beats.project_name + '.mp4';
const command = [
  'ffmpeg -y -hide_banner -loglevel error',
  inputs.join(' '),
  '-filter_complex ' + q(filters.join(';')),
  '-map [vout] -map [aout] -t ' + n(narrationSec + 0.4),
  '-c:v libx264 -preset medium -crf 23 -pix_fmt yuv420p -c:a aac -b:a 128k -movflags +faststart',
  q(outFile),
  '&& rm -rf ' + q(workDir),
].join(' ');

return [{ json: { command, outFile, narrationSec, shotCount: shots.length } }];

const pick = (d) => { const o = d.outputs || d.output || d.url; return Array.isArray(o) ? o[0] : o; };
const job = $('MuAPI job (called by this workflow)').item.json;
const requestId = $json.request_id || $json.id;
const url = requestId ? null : pick($json);
if (!requestId && !url) throw new Error('MuAPI returned neither a request id nor an output: ' + JSON.stringify($json));
return { json: { tag: job.tag, endpoint: job.endpoint, requestId, url: url || null, status: url ? 'completed' : 'pending', attempt: 0 } };

const pick = (d) => { const o = d.outputs || d.output || d.url; return Array.isArray(o) ? o[0] : o; };
// 90 polls x 10s = 15 minutes, enough for a Veo clip in a busy queue.
const MAX_ATTEMPTS = 90;
const prev = $('Wait 10s').item.json;
const attempt = prev.attempt + 1;
const raw = String($json.status || '').toLowerCase();
let status = 'pending';
if (raw === 'completed' || raw === 'succeeded') status = pick($json) ? 'completed' : 'failed';
else if (raw === 'failed' || raw === 'error' || raw === 'canceled') status = 'failed';
else if (attempt >= MAX_ATTEMPTS) status = 'failed';
return { json: { ...prev, attempt, status, url: status === 'completed' ? pick($json) : null, error: $json.error || null } };
